INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is the primary purpose of the blow room in a spinning mill?', '["To open, clean, and blend raw cotton fibers before carding","To twist yarn into its final form","To wind yarn onto cones","To dye the fiber before spinning"]'::jsonb, 'To open, clean, and blend raw cotton fibers before carding', 'The blow room is the first stage of spinning, where compressed cotton bales are opened, cleaned of trash (leaf, dust, seed coat), and blended before being fed to the carding machine.', 1, '{"blow-room"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'Which machine converts cotton fiber tufts into a continuous, loose rope-like strand called a sliver?', '["Carding machine","Ring frame","Simplex (speed frame)","Winding machine"]'::jsonb, 'Carding machine', 'The carding machine disentangles, cleans, and aligns fibers, delivering them as a continuous untwisted strand called sliver — often called the ''heart of spinning''.', 1, '{"carding"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What does ''Ne'' stand for in the English cotton count system?', '["Number English","Number of hanks (of 840 yards) per pound of yarn","Yarn elongation index","Net efficiency"]'::jsonb, 'Number of hanks (of 840 yards) per pound of yarn', 'Ne (English count) is an indirect count system: it equals the number of 840-yard hanks that weigh one pound. Higher Ne means finer yarn.', 1, '{"yarn-count"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'In the English cotton count system, which yarn is coarser?', '["10s Ne","40s Ne","60s Ne","80s Ne"]'::jsonb, '10s Ne', 'Ne is an indirect (inverse) count system — a LOWER Ne number means a COARSER (thicker) yarn, since fewer 840-yard hanks are needed to reach one pound.', 1, '{"yarn-count"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is the main function of the drawing (draw frame) process in spinning?', '["To blend multiple slivers and improve fiber parallelization/uniformity","To add the final twist to yarn","To remove color from raw fiber","To wind yarn into cones for shipping"]'::jsonb, 'To blend multiple slivers and improve fiber parallelization/uniformity', 'The draw frame doubles (combines) several card slivers and drafts them, which straightens and parallelizes fibers and evens out irregularities through the doubling effect.', 1, '{"draw-frame"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is ''drafting'' in the context of spinning?', '["Attenuating (thinning/stretching) a fiber strand to reduce its linear density","Twisting two yarns together","Dyeing fiber before spinning","Removing short fibers from a sliver"]'::jsonb, 'Attenuating (thinning/stretching) a fiber strand to reduce its linear density', 'Drafting means stretching a sliver or roving so fibers slide past each other, reducing the strand''s thickness (linear density) while increasing its length.', 1, '{"drafting"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'Which spinning preparatory machine produces ''roving'' from drawn sliver, adding a small amount of twist for strength?', '["Simplex / speed frame","Ring frame","Carding machine","Blow room"]'::jsonb, 'Simplex / speed frame', 'The simplex (speed frame / roving frame) further attenuates drawn sliver and inserts a light protective twist, producing roving that is wound onto bobbins for the ring frame.', 1, '{"roving","simplex"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is the main function of the ring frame in spinning?', '["To draft roving further and insert final twist to produce spun yarn","To open raw cotton bales","To dye finished yarn","To fold fabric after weaving"]'::jsonb, 'To draft roving further and insert final twist to produce spun yarn', 'The ring frame is the final spinning stage: it drafts roving to the desired fineness and inserts twist via the ring-and-traveler mechanism, producing finished spun yarn wound on bobbins.', 1, '{"ring-frame"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is the function of the traveler in ring spinning?', '["It rotates around the ring, guiding yarn onto the bobbin while inserting twist","It cuts the yarn at the end of a doff","It cleans the cotton sliver","It stores raw cotton bales"]'::jsonb, 'It rotates around the ring, guiding yarn onto the bobbin while inserting twist', 'The traveler is a small C-shaped clip that rides on the ring, dragged around by the yarn; the speed difference between spindle and traveler inserts twist and winds yarn onto the bobbin.', 1, '{"traveler","ring-frame"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What does ''twist per inch'' (TPI) measure in a spun yarn?', '["The number of twists (turns) inserted into the yarn per inch of its length","The yarn''s weight per unit length","The number of fibers in the yarn cross-section","The yarn''s color fastness rating"]'::jsonb, 'The number of twists (turns) inserted into the yarn per inch of its length', 'TPI (twist per inch) quantifies how many complete twists are inserted along one inch of yarn length; it directly affects yarn strength, hairiness, and handle.', 1, '{"twist"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'Which of these is generally TRUE about increasing twist in a spun yarn (within a normal range)?', '["It increases yarn strength up to an optimum point, then strength decreases","It always decreases yarn strength","It has no effect on yarn strength","It only affects yarn color"]'::jsonb, 'It increases yarn strength up to an optimum point, then strength decreases', 'As twist increases from zero, fibers grip each other better and strength rises; beyond an optimum twist level, the yarn axis becomes too oblique to fiber direction and strength starts to fall — this is the classic twist-strength curve.', 1, '{"twist","yarn-strength"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is the main purpose of the combing process (comber) in cotton spinning?', '["To remove short fibers and remaining impurities, improving fiber quality for fine yarns","To add twist to finished yarn","To dye the sliver","To wind yarn onto cones"]'::jsonb, 'To remove short fibers and remaining impurities, improving fiber quality for fine yarns', 'Combing removes short fibers (noil) and residual trash after carding/drawing, producing a more uniform, parallel fiber mass used for finer, stronger, smoother combed yarns.', 1, '{"combing"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is ''noil'' in the context of cotton combing?', '["The short fibers and waste removed during combing","The final spun yarn","The raw cotton bale before opening","The twist inserted in yarn"]'::jsonb, 'The short fibers and waste removed during combing', 'Noil is the by-product of combing — short fibers, neps, and trash removed to leave a cleaner, more uniform longer-fiber mass for spinning.', 1, '{"combing","noil"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'Which yarn type generally has better strength, smoothness, and evenness: combed or carded yarn (same count, same fiber)?', '["Combed yarn","Carded yarn","They are always identical","Neither — smoothness depends only on twist"]'::jsonb, 'Combed yarn', 'Combing removes short fibers and further aligns the remaining longer fibers, giving combed yarn better strength, evenness, and a smoother, less hairy surface than carded yarn of the same count.', 1, '{"combing","carded-yarn"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is ''winding'' in the yarn manufacturing process?', '["Transferring yarn from ring bobbins onto larger packages (cones/cheeses) while removing faults","Inserting the initial twist into roving","Opening raw cotton bales","Dyeing yarn before weaving"]'::jsonb, 'Transferring yarn from ring bobbins onto larger packages (cones/cheeses) while removing faults', 'Winding converts small ring-frame bobbins into large cones or cheeses suitable for downstream processes, while clearing devices remove thick/thin places and foreign fibers.', 1, '{"winding"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What does a ''yarn clearer'' do on a winding machine?', '["Detects and removes yarn faults such as thick places, thin places, and foreign matter","Inserts extra twist into the yarn","Dyes the yarn a uniform color","Measures the final yarn count only"]'::jsonb, 'Detects and removes yarn faults such as thick places, thin places, and foreign matter', 'Electronic yarn clearers continuously monitor yarn diameter/mass as it winds, cutting out and splicing over faults like slubs, thick/thin places, and foreign fibers.', 1, '{"winding","yarn-clearer"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is the typical raw material processing sequence in conventional ring spinning (short-staple cotton)?', '["Blow room → Carding → Drawing → Simplex → Ring frame → Winding","Ring frame → Carding → Blow room → Winding → Simplex","Winding → Blow room → Ring frame → Carding → Drawing","Carding → Blow room → Winding → Drawing → Ring frame"]'::jsonb, 'Blow room → Carding → Drawing → Simplex → Ring frame → Winding', 'The standard ring-spinning sequence is: blow room (opening/cleaning) → carding (sliver formation) → drawing (blending/parallelizing) → simplex (roving formation) → ring frame (final spinning) → winding (package formation).', 1, '{"spinning-sequence"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is ''open-end (rotor) spinning'' fundamentally different from in comparison to ring spinning?', '["It breaks the fiber flow (feeding individualized fibers into a rotor) rather than continuously drafting a strand under tension","It only works with synthetic fibers, never cotton","It does not insert any twist into the yarn","It produces yarn without any bobbin or package"]'::jsonb, 'It breaks the fiber flow (feeding individualized fibers into a rotor) rather than continuously drafting a strand under tension', 'In rotor (open-end) spinning, sliver is opened into individual fibers by a combing roller, fed into a rotating rotor, and twisted as new fibers are continuously added — the fiber stream is ''open-ended'' rather than a continuously drafted, tensioned strand as in ring spinning.', 1, '{"rotor-spinning"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'Compared to ring-spun yarn, rotor (open-end) spun yarn typically has:', '["Lower strength and a bulkier, more even but slightly harsher handle","Higher strength and a smoother handle in all cases","Identical properties in every respect","No twist at all"]'::jsonb, 'Lower strength and a bulkier, more even but slightly harsher handle', 'Rotor yarn generally has lower tenacity than ring yarn of the same count (due to wrapper fibers and structure) but is bulkier, more even, and produced at much higher speed/lower cost, suited to coarser, everyday fabrics.', 1, '{"rotor-spinning","ring-spinning"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is ''moisture regain'' of a textile fiber?', '["The weight of moisture in a fiber expressed as a percentage of the fiber''s oven-dry weight","The maximum tensile strength of a wet fiber","The color change of fiber when wet","The amount of oil applied to fiber during processing"]'::jsonb, 'The weight of moisture in a fiber expressed as a percentage of the fiber''s oven-dry weight', 'Moisture regain % = (weight of moisture / oven-dry weight of fiber) × 100. It''s a standard property used for conditioning fiber/yarn before testing and for commercial weight calculations.', 1, '{"moisture-regain"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'Why is a small amount of moisture regain generally desirable for cotton fiber during spinning?', '["It helps fiber flexibility and reduces static/fiber breakage during processing","It permanently increases fiber color brightness","It eliminates the need for any twist in yarn","It converts cotton into a synthetic fiber"]'::jsonb, 'It helps fiber flexibility and reduces static/fiber breakage during processing', 'Adequate moisture keeps cotton fiber pliable and reduces static electricity and fiber breakage during high-speed processing; too dry or too humid conditions both cause processing problems.', 1, '{"moisture-regain","cotton"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What does ''staple length'' of cotton fiber refer to?', '["The average length of the fibers in a cotton sample","The diameter (fineness) of a single fiber","The strength of a single fiber","The twist level of the finished yarn"]'::jsonb, 'The average length of the fibers in a cotton sample', 'Staple length is the characteristic (average) length of fibers in a cotton sample, a key quality parameter that influences what yarn count/quality can be spun from it.', 1, '{"staple-length"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'Generally, longer cotton staple length allows spinning:', '["Finer, stronger yarn with fewer fiber ends per cross-section needed for strength","Only coarser, weaker yarn","Yarn with no twist at all","Yarn that cannot be dyed"]'::jsonb, 'Finer, stronger yarn with fewer fiber ends per cross-section needed for strength', 'Longer fibers create more fiber-to-fiber contact/overlap per unit length, so fewer fibers in the yarn cross-section are needed to achieve adequate strength — enabling finer, stronger yarns from long-staple cotton.', 1, '{"staple-length","yarn-strength"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is ''micronaire'' a measure of in cotton fiber testing?', '["Fiber fineness and maturity (via airflow resistance)","Fiber color grade only","Fiber staple length only","Yarn twist level"]'::jsonb, 'Fiber fineness and maturity (via airflow resistance)', 'Micronaire value is determined by measuring the airflow resistance of a compressed fiber plug; it reflects a combination of fiber fineness and maturity, important for spinning performance and dye uptake.', 1, '{"micronaire","cotton-quality"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is the purpose of ''lap'' formation in the blow room / comber preparatory process?', '["To form a uniform, flat sheet of fiber wound into a roll for feeding to the comber","To twist yarn into its final form","To dye raw fiber","To wind finished yarn onto cones"]'::jsonb, 'To form a uniform, flat sheet of fiber wound into a roll for feeding to the comber', 'A lap is a uniform flat sheet of fiber wound onto a roll, typically produced by a lap former (sliver lap or ribbon lap machine) as feed material for the combing machine.', 1, '{"lap-formation"}'::text[]);
INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is a ''nep'' in cotton fiber/yarn?', '["A small tangled knot of fibers that appears as a visible imperfection","The final twisted yarn structure","A type of cotton bale packaging","The moisture content indicator"]'::jsonb, 'A small tangled knot of fibers that appears as a visible imperfection', 'A nep is a small, tightly tangled knot of fibers (sometimes including trash) that forms during processing; high nep counts create visible defects in yarn and fabric.', 1, '{"nep"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'Which machine in the spinning process is primarily responsible for removing neps and short fibers through a series of doubling and drafting passages while also blending?', '["Draw frame (multiple passages help even out and reduce imperfections)","Ring frame","Winding machine","Blow room only"]'::jsonb, 'Draw frame (multiple passages help even out and reduce imperfections)', 'While carding removes many neps and drawing mainly blends/parallelizes, multiple drawing passages progressively even out irregularities from carding and reduce residual imperfections through the doubling and drafting action.', 1, '{"draw-frame","nep"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is the primary reason cotton bales must be ''opened'' at the start of spinning?', '["To loosen tightly compressed, densely packed fiber tufts so they can be cleaned and processed","To add color to the raw fiber","To directly produce finished yarn","To measure the exact weight of each bale"]'::jsonb, 'To loosen tightly compressed, densely packed fiber tufts so they can be cleaned and processed', 'Cotton arrives in densely compressed bales; opening breaks up these compressed tufts into smaller, looser clumps so that cleaning machinery can effectively remove trash and prepare the fiber for carding.', 1, '{"bale-opening"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What does ''count variation'' (or count CV%) indicate about a batch of spun yarn?', '["How consistently the yarn count (linear density) is maintained across samples/bobbins","The color consistency of the yarn","The twist direction of the yarn","The packaging material used for the yarn"]'::jsonb, 'How consistently the yarn count (linear density) is maintained across samples/bobbins', 'Count CV% (coefficient of variation) measures how much the actual yarn count varies from sample to sample around the target/nominal count — lower CV% means more consistent, higher-quality yarn.', 1, '{"count-variation"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'In ring spinning, what is the role of the ''ring rail''?', '["It moves up and down to build the yarn package evenly on the bobbin (traverse motion)","It measures the moisture content of the fiber","It cleans raw cotton before carding","It dyes the finished yarn"]'::jsonb, 'It moves up and down to build the yarn package evenly on the bobbin (traverse motion)', 'The ring rail, carrying the rings and travelers, moves up and down in a controlled traverse motion so yarn winds evenly along the bobbin''s length, building a proper cop/package shape.', 1, '{"ring-frame","ring-rail"}'::text[]);
